public static void main(Args _args)
{
    var accNum = XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateCustomer, "CustAccount");
    if(CustTable::find(accNum).RecId != 0)
    {

        XAPI_API_AutomationFacade::cleanup_Customer(accNum);
        XAPI_APILogTable::archive();
        XAPI_API_AutomationFacade::cleanup_dependentData();
    }
    else 
    {
        throw Error("no cust found");
    }
}
